{
  "format": "compare-outcomes/1",
  "module": {
    "id": "learning-support-outcomes",
    "version": "1.1.0",
    "title": "Compare learning-support plans",
    "description": "Compare the next six-week support block for a fictional eight-year-old whose dyslexia and ADHD have already been professionally assessed. A positive classroom report can coexist with persistent decoding difficulty; renewing support on one overall success judgment could leave another need insufficiently addressed. Every response range is an authored assumption, not a validated prediction or a confidence interval. The classroom package is support for attention-related difficulties, not a complete clinical ADHD treatment. Separate progress measures inform reconsideration; before-and-after change alone does not establish a causal effect.",
    "question": "Which support plan will help this child—and what improvement would show that it is working?",
    "boundary": "Compare the next six-week support block for a fictional eight-year-old whose dyslexia and ADHD have already been professionally assessed. A positive classroom report can coexist with persistent decoding difficulty; renewing support on one overall success judgment could leave another need insufficiently addressed. Every response range is an authored assumption, not a validated prediction or a confidence interval. The classroom package is support for attention-related difficulties, not a complete clinical ADHD treatment. Separate progress measures inform reconsideration; before-and-after change alone does not establish a causal effect.",
    "alternatives": [
      {
        "id": "reading-support",
        "label": "Targeted word-reading support",
        "description": "A complete word-reading support package for this comparison. Its assumed decoding benefit does not automatically establish improvement in attention-related classroom difficulties."
      },
      {
        "id": "classroom-support",
        "label": "Classroom support for attention-related difficulties",
        "description": "A complete classroom-support package for this comparison, not a complete clinical ADHD treatment. Completing more work is not treated as evidence of better word decoding."
      },
      {
        "id": "coordinated-support",
        "label": "Coordinated support",
        "description": "A coordinated package addressing both recorded needs, with greater weekly burden. It is not assumed to dominate the focused alternatives."
      }
    ],
    "outcomes": [
      {
        "id": "word-reading",
        "label": "Word-reading improvement",
        "unit": "change in correct items on a fixed 20-item decoding probe",
        "direction": "maximize",
        "minimum": -6,
        "maximum": 14,
        "description": "Change from this fictional case’s baseline of 6 correct items out of 20. Negative change remains possible. The fixed baseline defines the permitted change range; another baseline requires an adapted model. It is separate from work completed."
      },
      {
        "id": "participation",
        "label": "Classroom-participation improvement",
        "unit": "percentage-point change in engaged observation intervals",
        "direction": "maximize",
        "minimum": -45,
        "maximum": 55,
        "description": "Change from this fictional case’s baseline of 45% under a fixed classroom observation protocol. Negative change remains possible. It is not an ADHD diagnosis or a measure of decoding."
      },
      {
        "id": "weekly-burden",
        "label": "Additional weekly burden",
        "unit": "minutes per week",
        "direction": "minimize",
        "minimum": 0,
        "maximum": 600,
        "description": "Additional practice and coordination time borne by the child and family. It is kept separate from improvement rather than converted into money."
      }
    ],
    "assumptions": [
      "Dyslexia and ADHD have already been professionally assessed in this fictional case; the calculation does not diagnose them or determine clinical suitability.",
      "The decision concerns the next six-week support block. Better classroom participation does not by itself establish that the decoding need is sufficiently addressed; decoding improvement does not by itself establish adequate classroom functioning.",
      "All alternatives are complete authored support descriptions for this bounded comparison. Classroom support for attention-related difficulties is not a complete clinical ADHD treatment. The range comparison does not prescribe medication, infer clinical efficacy or produce a probability of benefit.",
      "Targets and priority order are explicit human judgments. A preferred option is conditional on supplied estimates, applicability and preferences; overlapping ranges can leave the choice unresolved.",
      "The six-week horizon and baseline values are fictional teaching inputs. Qualified professionals must choose appropriate measures and reconsideration criteria."
    ],
